// Artwork generated by scripts/generate-art.py. Each image exists in several
// widths so the browser can pick the smallest one that is sharp on the screen.
const files = import.meta.glob('../../assets/images/*.webp', { eager: true, import: 'default' });

const urlFor = (name, width) => files[`../../assets/images/${name}-${width}.webp`];

const SETS = {
  characters: { prefix: 'character', count: 4, widths: [600, 1200], ratio: [1, 1] },
  planets: { prefix: 'planet', count: 3, widths: [600, 1200], ratio: [1, 1] },
  starships: { prefix: 'starship', count: 6, widths: [720, 1600], ratio: [16, 9] },
  films: { prefix: 'film', count: 3, widths: [720, 1600], ratio: [16, 9] },
  species: { prefix: 'species', count: 4, widths: [600, 1200], ratio: [1, 1] },
  vehicles: { prefix: 'vehicle', count: 4, widths: [720, 1600], ratio: [16, 9] },
};

const imageSet = (name, widths, [rw, rh]) => ({
  src: urlFor(name, widths[0]),
  srcSet: widths.map(width => `${urlFor(name, width)} ${width}w`).join(', '),
  width: widths[0],
  height: Math.round(widths[0] * rh / rw),
});

// The same item always gets the same picture, wherever it is shown
const stableIndex = (text, count) => {
  let hash = 0;
  for (let i = 0; i < text.length; i++) {
    hash = (hash * 31 + text.charCodeAt(i)) >>> 0;
  }
  return hash % count;
};

const pick = (name, choices) => choices[stableIndex(name, choices.length)];

// Rules matching what the API says about an item to the artwork that shows it.
// Each returns the image numbers to choose from; null falls back to any image.
const MATCHERS = {
  characters: (item) => {
    // SWAPI's droid species is /species/2/; droid names also tend to carry digits
    const isDroid = (item.species || []).some(url => /\/species\/2\/?$/.test(url)) || /\d/.test(item.name);
    // 1 hooded wanderer, 2 armoured sentinel, 3 pilot, 4 droid
    return isDroid ? [4] : [1, 2, 3];
  },
  // Scores each biome by keywords; climate counts double because it describes
  // the whole world while terrain lists every feature on it
  planets: (item) => {
    const climate = (item.climate || '').toLowerCase();
    const terrain = (item.terrain || '').toLowerCase();
    const BIOMES = [
      [1, /arid|hot|superheated|dry/g, /desert|barren|rock|volcano|lava|ash|canyon|mesa|scrub|dune/g],
      [2, /frozen|frigid|artic|arctic|subartic|cold/g, /ice|glacier|tundra|snow/g],
      [3, /temperate|tropical|humid|moist|murky|wet/g, /ocean|sea|lake|jungle|forest|swamp|grass|reef|island|bog|river|verdant|rainforest/g],
    ];
    const scored = BIOMES.map(([image, climateWords, terrainWords]) => [
      image,
      2 * (climate.match(climateWords) || []).length + (terrain.match(terrainWords) || []).length,
    ]);
    const best = Math.max(...scored.map(([, score]) => score));
    return best > 0 ? [scored.find(([, score]) => score === best)[0]] : null;
  },
  starships: (item) => {
    const text = `${item.starship_class || ''} ${item.model || ''} ${item.name}`.toLowerCase();
    // 1 capital ship, 2 fighter, 3 freighter, 4 interceptor, 5 corvette, 6 shuttle
    if (/star destroyer|destroyer|cruiser|battleship|dreadnought|battle ?station|control (ship|station)|assault ship|carrier/.test(text)) return [1];
    if (/corvette|frigate|gunship|escort/.test(text)) return [5];
    if (/shuttle|landing craft|yacht|barge|patrol|lander/.test(text)) return [6];
    if (/freighter|transport|cargo|container|hauler/.test(text)) return [3];
    if (/fighter|bomber|interceptor|wing|assault|scout|tie/.test(text)) return [2, 4];
    return null;
  },
  // 1 prequel era, 2 original era, 3 anything later
  films: (item) => {
    const episode = Number(item.episode_id);
    if (episode >= 1 && episode <= 3) return [1];
    if (episode >= 4 && episode <= 6) return [2];
    if (episode >= 7) return [3];
    return null;
  },
  species: (item) => {
    const text = `${item.classification || ''} ${item.designation || ''}`.toLowerCase();
    // 1 humanoid, 2 reptilian, 3 insectoid, 4 artificial
    if (/artificial|droid|synthetic/.test(text)) return [4];
    if (/reptil|saurian|amphibian/.test(text)) return [2];
    if (/insectoid|arthropod|mollusk|gastropod|cephalopod/.test(text)) return [3];
    if (/mammal|human|primate|wookiee/.test(text)) return [1];
    return null;
  },
  vehicles: (item) => {
    const text = `${item.vehicle_class || ''} ${item.model || ''} ${item.name}`.toLowerCase();
    // 1 walker, 2 speeder, 3 heavy ground transport, 4 atmospheric flyer
    if (/walker|legged/.test(text)) return [1];
    if (/speeder|repulsorcraft|hover/.test(text)) return [2];
    if (/wheeled|tracked|tank|digger|crawler|harvester|transport|carrier|barge|sail/.test(text)) return [3];
    if (/starfighter|fighter|bomber|gunship|glider|assault|airspeeder/.test(text)) return [4];
    return null;
  },
};

// `item` is an API item, or anything with a name
export const artworkFor = (category, item = {}) => {
  const set = SETS[category];
  if (!set) return null;
  const subject = typeof item === 'string' ? { name: item } : item;
  const name = (subject.name || '').toLowerCase();
  const all = Array.from({ length: set.count }, (_, i) => i + 1);
  const choices = MATCHERS[category](subject) || all;
  return imageSet(`${set.prefix}-${pick(name, choices)}`, set.widths, set.ratio);
};

export const heroArtwork = imageSet('hero', [1280, 1920, 2880], [2880, 1240]);

// Full-screen background for the loader
export const heroBackground = urlFor('hero', 1920);

// Rendered sizes of the artwork in each layout, so srcset picks the right file
export const SIZES = {
  // Square image beside the text: 300px, 250px between 500-900px wide screens
  side: '(max-width: 500px) 250px, (max-width: 768px) 300px, (max-width: 900px) 250px, 300px',
  // Image above the text: fills the card, three cards a row on wide screens
  top: '(max-width: 768px) 90vw, 400px',
  // Description page: 65% of the hero body, which is at most 800px wide
  description: '(max-width: 800px) 65vw, 520px',
  hero: '100vw',
};
